// The VALUE-position control for `bangvoid`. Same forcing `!`, same void
// operand, but the boolean is KEPT -- so ToBoolean actually has to produce
// one, and the operand's type has none. This must stay refused.
//
// It has to live in a shipped package rather than in the program, because
// tsc refuses `!voidCall()` in program-owned TS outright ("An expression
// of type 'void' cannot be tested for truthiness", SC0001) and the
// program never reaches the lowering at all.
function nothing() {
    // returns undefined; inference gives the call type `void`
}

var forced = !nothing();

exports.forced = forced;
exports.ok = true;
